<?php $hero=['title'=>'مسئله‌ات را بگو؛ از تجربه‌اش شروع کن.','text'=>'تجربه‌های واقعی را بخوان و مستقیم با کسی گفت‌وگو کن که این مسیر را رفته است.','eyebrow'=>'گفت‌وگو با کسی که این مسیر را رفته'];$heroEnabled=true;foreach($blocks as $b){if($b['type']==='hero'){$hero=$b;$heroEnabled=empty($b['hidden']);break;}} ?>
<?php if($heroEnabled): ?><section class="hero"><div><span class="eyebrow"><?= $this->icon('chat') ?><?= $this->copy($hero['eyebrow']??'') ?></span><h1><?= $this->copy($hero['title']) ?></h1><p><?= nl2br($this->copy($hero['text'])) ?></p>
<form class="home-search" method="get" action="<?= $this->h($this->url('/search')) ?>"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/search"><?php endif; ?><label class="sr-only" for="home-search">مسئله یا تجربه موردنظر</label><input id="home-search" name="q" maxlength="160" placeholder="دنبال چه تجربه‌ای هستی؟"><button class="primary">جست‌وجو</button></form></div><div class="hero-art" style="--hero-logo-size:<?= (int)($hero['logo_size']??240) ?>px"><span class="hero-orbit"></span><img class="hero-logo" src="/assets/morshed-logo-transparent-288.png" width="240" height="240" alt="مرشد؛ یک تجربه، یک مسیر تازه"><span class="hero-caption">تجربه، آغاز یک گفت‌وگو</span></div></section><?php endif; ?>
<?php foreach($blocks as $index=>$block): if($block['type']==='hero'){continue;}$kind=$block['type'];$all=match($kind){'mentors'=>'/mentors','experiences'=>'/experiences','topics'=>'/experiences','issues'=>'/experiences',default=>null}; ?>
<section class="section storefront-section"><div class="section-head"><h2><?= $this->copy($block['title']) ?></h2><?php if($all): ?><a class="textlink" href="<?= $this->h($this->url($all)) ?>">مشاهدهٔ همه <?= $this->icon('arrow') ?></a><?php endif; ?></div>
<?php if($block['text']): ?><p class="prose muted"><?= nl2br($this->copy($block['text'])) ?></p><?php endif; ?>
<?php if(in_array($kind,['mentors','experiences','topics','issues'],true)): ?>
<?php if($block['items']): ?><?php $isClassification=in_array($kind,['topics','issues'],true);$railId='home-row-'.$index; ?><div id="<?= $railId ?>" class="<?= $isClassification?'thumbnail-rail':(($block['layout']??'rail')==='grid'?'grid3':'card-rail') ?>" tabindex="0" role="region" aria-label="<?= $this->copy($block['title']) ?>؛ برای دیدن موارد بیشتر افقی پیمایش کنید">
<?php foreach($block['items'] as $item): if($isClassification): $topic=$item; ?><a class="thumbnail-topic" href="<?= $this->h($this->url(($kind==='issues'?'/experiences?issue=':'/experiences?topic=').$topic['id'])) ?>"><span><?php if(!empty($topic['icon_asset_id'])): ?><img src="<?= $this->h($this->url('/content/asset?id='.$topic['icon_asset_id'])) ?>" width="64" height="64" loading="lazy" alt=""><?php else: ?><?= $this->icon($topic['icon']??'topic') ?><?php endif; ?></span><strong><?= $this->h(($kind==='issues'?($topic['short_label']??''):'')?:$topic['title']) ?></strong></a>
<?php elseif($kind==='mentors'): $row=$item;require __DIR__.'/mentor-card.php'; ?>
<?php else: $row=$item;require __DIR__.'/experience-card.php'; ?><?php endif; endforeach; ?></div>
<?php else: ?><p class="empty card muted">هنوز <?= $kind==='mentors'?'مرشد‌ای':($kind==='experiences'?'تجربه‌ای':'موضوعی') ?> برای این بخش منتشر نشده است.</p><?php endif; endif; ?></section><?php endforeach; ?>
<section class="section how-it-works" aria-labelledby="steps-title"><div class="section-head"><div><span class="eyebrow">از جست‌وجو تا گفت‌وگو</span><h2 id="steps-title">سه قدم تا یک گفت‌وگوی مفید</h2></div></div><ol class="journey-steps"><li><span class="journey-icon"><?= $this->icon('book') ?></span><span class="journey-number">۰۱</span><h3>مسئله‌ات را پیدا کن</h3><p>در تجربه‌ها جست‌وجو کن و مسیرهای مرتبط را بخوان.</p></li><li><span class="journey-icon"><?= $this->icon('users') ?></span><span class="journey-number">۰۲</span><h3>مرشد را بشناس</h3><p>تجربه‌ها و معرفی مرشد را ببین و فرد مناسب را انتخاب کن.</p></li><li><span class="journey-icon"><?= $this->icon('chat') ?></span><span class="journey-number">۰۳</span><h3>گفت‌وگو را شروع کن</h3><p>از مرشد دربارهٔ جزئیات مسیری که رفته بپرس.</p></li></ol></section>
